using ModelContextProtocol;
using System.ComponentModel;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddMcpServer()
    .WithHttpTransport()
    .WithToolsFromAssembly()
    .WithResources();

var app = builder.Build();

app.MapMcp();

app.Run();

// --- Tools ---

[McpServerToolType]
public static class EchoTool
{
    [McpServerTool, Description("Echoes the input message back")]
    public static string Echo(string message) => $"Echo: {message}";
}

[McpServerToolType]
public static class TimeTool
{
    [McpServerTool, Description("Returns the current server time in UTC")]
    public static string GetTime() => DateTime.UtcNow.ToString("o");
}

// --- Resources ---

[McpServerResourceType]
public static class ConfigResource
{
    [McpServerResource(
        UriTemplate = "config://app/settings",
        Name = "App Settings",
        Description = "Returns application configuration data")]
    public static string GetSettings()
    {
        var config = new
        {
            AppName = "McpHttpServer",
            Version = "1.0.0",
            Environment = "Development",
            Features = new { Logging = true, Caching = false }
        };
        return System.Text.Json.JsonSerializer.Serialize(config, 
            new System.Text.Json.JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(
        UriTemplate = "config://app/endpoints",
        Name = "API Endpoints",
        Description = "Lists available API endpoints")]
    public static string GetEndpoints()
    {
        var endpoints = new[]
        {
            new { Path = "/mcp", Method = "POST", Description = "MCP endpoint" },
            new { Path = "/mcp/sse", Method = "GET", Description = "MCP SSE endpoint" }
        };
        return System.Text.Json.JsonSerializer.Serialize(endpoints,
            new System.Text.Json.JsonSerializerOptions { WriteIndented = true });
    }
}

